const teamClaimTotals = `-- name: TeamClaimTotals :many
SELECT currency, count(*)::int AS claims, coalesce(sum(amount), 0)::numeric(14, 2)::text AS amount
FROM claim
WHERE status <> 'draft'
  AND ($1::text IS NULL OR status = $1)
  AND ($2::text IS NULL OR user_id = $2)
  AND ($3::date IS NULL OR coalesce(receipt_date, created_at::date) >= $3)
  AND ($4::date IS NULL OR coalesce(receipt_date, created_at::date) <= $4)
GROUP BY currency
ORDER BY sum(amount) DESC NULLS LAST, currency
`

type TeamClaimTotalsParams struct {
	Status   *string
	UserID   *string
	FromDate pgtype.Date
	ToDate   pgtype.Date
}

type TeamClaimTotalsRow struct {
	Currency string
	Claims   int32
	Amount   string
}

func (q *Queries) TeamClaimTotals(ctx context.Context, arg TeamClaimTotalsParams) ([]TeamClaimTotalsRow, error) {
	rows, err := q.db.Query(ctx, teamClaimTotals,
		arg.Status,
		arg.UserID,
		arg.FromDate,
		arg.ToDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TeamClaimTotalsRow
	for rows.Next() {
		var i TeamClaimTotalsRow
		if err := rows.Scan(&i.Currency, &i.Claims, &i.Amount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

